@using sv_201779e69fc84c3eaccc5abd74298a60.Models

<div class="card p-3" style="@PreviewStyle()">
    <h6 style="margin-bottom: 0.75rem;">Preview</h6>
    <p style="margin-bottom: 0.5rem;">This is a sample paragraph showing your appearance preferences.</p>
    <div class="d-flex gap-2 align-items-center">
        <button class="btn btn-primary btn-sm">Primary Button</button>
        <button class="btn btn-outline-secondary btn-sm">Secondary</button>
        <span class="badge bg-info">Badge</span>
    </div>
    <hr />
    <ul class="mb-0" style="@(Settings.CompactMode ? "padding-left:1rem;margin-bottom:0;" : "")">
        <li>List item one</li>
        <li>List item two</li>
        <li>List item three</li>
    </ul>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;

    private string PreviewStyle()
    {
        var bg = Settings.Theme switch
        {
            "Dark" => "background-color:#1e1e1e;color:#e0e0e0;",
            "System" => "background-color:#f0f0f0;color:#333;",
            _ => "background-color:#ffffff;color:#212529;"
        };

        var fontSize = Settings.FontSize switch
        {
            "Small" => "font-size:0.85rem;",
            "Large" => "font-size:1.15rem;",
            _ => "font-size:1rem;"
        };

        var spacing = Settings.CompactMode
            ? "padding:0.5rem !important;line-height:1.3;"
            : "";

        return $"{bg}{fontSize}{spacing}";
    }
}

