@using sv_201779e69fc84c3eaccc5abd74298a60.Models

<h4 class="mb-4">Profile</h4>

@if (_message is not null)
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-8">
        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="_bio"></textarea>
        </div>
    </div>

    <div class="col-md-4 text-center">
        <div class="mb-2">
            <img src="@Profile.AvatarUrl" alt="Avatar" class="rounded-circle border"
                 style="width:128px;height:128px;object-fit:cover;" />
        </div>
        <small class="text-muted text-break">@Profile.AvatarUrl</small>
    </div>
</div>

<div class="d-flex gap-2 mt-3">
    <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
        @(_saving ? "Saving…" : "Save Changes")
    </button>
    <button class="btn btn-outline-secondary" @onclick="DiscardChanges">
        Discard Changes
    </button>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string? _message;
    private bool _saving;

    protected override void OnParametersSet()
    {
        if (!_saving)
        {
            ResetFields();
        }
    }

    private void ResetFields()
    {
        _displayName = Profile.DisplayName;
        _email = Profile.Email;
        _bio = Profile.Bio;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        try
        {
            var updated = Profile with
            {
                DisplayName = _displayName,
                Email = _email,
                Bio = _bio
            };
            await OnSave.InvokeAsync(updated);
            _message = "Profile saved successfully!";
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardChanges()
    {
        ResetFields();
        _message = null;
    }
}

@using sv_201779e69fc84c3eaccc5abd74298a60.Models

<h4 class="mb-4">Notifications</h4>

@if (_message is not null)
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<div class="mb-4">
    <h6>Notification Channels</h6>

    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="emailNotif"
               checked="@_emailNotifications"
               @onchange="e => _emailNotifications = (bool)(e.Value ?? false)" />
        <label class="form-check-label" for="emailNotif">Email Notifications</label>
    </div>

    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="pushNotif"
               checked="@_pushNotifications"
               @onchange="e => _pushNotifications = (bool)(e.Value ?? false)" />
        <label class="form-check-label" for="pushNotif">Push Notifications</label>
    </div>

    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="weeklyDigest"
               checked="@_weeklyDigest"
               @onchange="e => _weeklyDigest = (bool)(e.Value ?? false)" />
        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
    </div>
</div>

<div class="mb-4">
    <h6>Muted Channels</h6>
    <p class="text-muted small">Uncheck channels you want to receive notifications from.</p>

    @foreach (var channel in _channels)
    {
        <div class="form-check mb-1">
            <input class="form-check-input" type="checkbox" id="@($"ch-{channel.Name}")"
                   checked="@channel.IsMuted"
                   @onchange="e => channel.IsMuted = (bool)(e.Value ?? false)" />
            <label class="form-check-label text-capitalize" for="@($"ch-{channel.Name}")">
                @channel.Name
            </label>
        </div>
    }
</div>

<button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
    @(_saving ? "Saving…" : "Save Preferences")
</button>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<ChannelState> _channels = [];
    private string? _message;
    private bool _saving;

    protected override void OnParametersSet()
    {
        if (!_saving)
        {
            _emailNotifications = Prefs.EmailNotifications;
            _pushNotifications = Prefs.PushNotifications;
            _weeklyDigest = Prefs.WeeklyDigest;
            _channels = Prefs.MutedChannels
                .Select(c => new ChannelState { Name = c, IsMuted = true })
                .ToList();
        }
    }

    private async Task SavePreferences()
    {
        _saving = true;
        try
        {
            var mutedChannels = _channels.Where(c => c.IsMuted).Select(c => c.Name).ToList();
            var updated = new NotificationPrefs(
                _emailNotifications,
                _pushNotifications,
                _weeklyDigest,
                mutedChannels);
            await OnSave.InvokeAsync(updated);
            _message = "Notification preferences saved!";
        }
        finally
        {
            _saving = false;
        }
    }

    private class ChannelState
    {
        public string Name { get; set; } = "";
        public bool IsMuted { get; set; }
    }
}

@using sv_201779e69fc84c3eaccc5abd74298a60.Models

<h4 class="mb-4">Security</h4>

<div class="mb-4">
    <ChangePasswordPanel OnChangePassword="HandlePasswordChange" />
</div>

<div class="card mb-4">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center">
            <div>
                <h6 class="mb-1">Two-Factor Authentication</h6>
                <small class="text-muted">
                    @if (Security.TwoFactorEnabled)
                    {
                        <span class="text-success">● Enabled</span>
                    }
                    else
                    {
                        <span class="text-warning">● Disabled</span>
                    }
                </small>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox"
                       checked="@Security.TwoFactorEnabled"
                       @onchange="HandleTwoFactorToggle" />
            </div>
        </div>
    </div>
</div>

@if (Security.LastPasswordChange.HasValue)
{
    <p class="text-muted small mb-4">
        Last password change: @Security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
    </p>
}

<ActiveSessionsTable
    Sessions="Security.Sessions"
    OnRevoke="OnRevokeSession" />

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter, EditorRequired] public EventCallback<bool> OnTwoFactorToggle { get; set; }

    private async Task HandlePasswordChange((string Current, string New) args) =>
        await OnChangePassword.InvokeAsync(args);

    private async Task HandleTwoFactorToggle(ChangeEventArgs e) =>
        await OnTwoFactorToggle.InvokeAsync((bool)(e.Value ?? false));
}

@using sv_201779e69fc84c3eaccc5abd74298a60.Models

<h4 class="mb-4">Appearance</h4>

@if (_message is not null)
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-6">
        <div class="mb-4">
            <h6>Theme</h6>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme"
                           id="@($"theme-{theme}")"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Font Size</h6>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize"
                           id="@($"fs-{size}")"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Language</h6>
            <select class="form-select" @bind="_language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode"
                       checked="@_compactMode"
                       @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
