        <button class="btn btn-primary" @onclick="Save" disabled="@_saving">
            @(_saving ? "Saving…" : "Save")
        </button>
    </div>

    <div class="col-md-6">
        <h6 class="mb-2">Live Preview</h6>
        <AppearancePreview Settings="@CurrentPreview" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Appearance { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private string? _message;
    private bool _saving;

    private AppearanceSettings CurrentPreview =>
        new(_theme, _fontSize, _language, _compactMode);

    protected override void OnParametersSet()
    {
        if (!_saving)
        {
            _theme = Appearance.Theme;
            _fontSize = Appearance.FontSize;
            _language = Appearance.Language;
            _compactMode = Appearance.CompactMode;
        }
    }

    private async Task Save()
    {
        _saving = true;
        try
        {
            await OnSave.InvokeAsync(CurrentPreview);
            _message = "Appearance settings saved!";
        }
        finally
        {
            _saving = false;
        }
    }
}

