@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<h3 class="mb-4">Settings</h3>

@if (_loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else
{
    <div class="settings-layout">
        <aside class="settings-nav">
            <SettingsSidebar ActiveTab="@_activeTab" OnTabChanged="tab => _activeTab = tab" />
        </aside>

        <section class="settings-content">
            @switch (_activeTab)
            {
                case "Profile":
                    <ProfileSection Profile="@_profile!" OnSave="SaveProfile" />
                    break;

                case "Notifications":
                    <NotificationsSection Prefs="@_prefs!" OnSave="SaveNotifications" />
                    break;

                case "Security":
                    <SecuritySection
                        Security="@_security!"
                        OnChangePassword="ChangePassword"
                        OnRevokeSession="RevokeSession"
                        OnTwoFactorToggle="ToggleTwoFactor" />
                    break;

                case "Appearance":
                    <AppearanceSection Appearance="@_appearance!" OnSave="SaveAppearance" />
                    break;
            }
        </section>
    </div>
}

@code {
    private string _activeTab = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _prefs;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        _loading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var prefsTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, prefsTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _prefs = prefsTask.Result;
        _security = securityTask.Result;
        _appearance = appearanceTask.Result;
    }

    private async Task SaveProfile(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
    }

    private async Task SaveNotifications(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
    }

    private async Task ChangePassword((string Current, string New) args) =>
        await SettingsService.ChangePasswordAsync(args.Current, args.New);

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task ToggleTwoFactor(bool enabled)
    {
        // In a real app this would call a service method
        _security = _security! with { TwoFactorEnabled = enabled };
        await Task.CompletedTask;
    }

    private async Task SaveAppearance(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
    }
}

