    display: flex;
    gap: 2rem;
    min-height: 500px;
}

.settings-nav {
    flex: 0 0 200px;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-sidebar .nav-link {
    color: var(--bs-body-color);
    border-radius: 0.375rem;
